def total_cost(cm, fp_cost, fn_cost):
    '''Expected cost = fp * fp_cost + fn * fn_cost; ValueError on missing keys.'''
    for key in ('tp', 'fp', 'fn', 'tn'):
        if key not in cm:
            raise ValueError('confusion dict needs the keys tp, fp, fn, tn')
    return float(cm['fp'] * fp_cost + cm['fn'] * fn_cost)

def best_threshold(y_prob, y_true, fp_cost, fn_cost):
    '''Sweep t = 0.1 .. 0.9 (rule p >= t); minimal cost wins, ties -> smallest t.'''
    best_t = None
    best_cost = None
    for i in range(1, 10):
